{
  "requirements": [
    {
      "id": "support-role",
      "description": "Serve the Acme support team by answering short general-knowledge questions.",
      "source": "AGENTS.md"
    },
    {
      "id": "sentence-limit",
      "description": "Answer in one or two sentences, including the required motto closing.",
      "source": "AGENTS.md"
    },
    {
      "id": "exact-motto-closing",
      "description": "Close every reply with the team motto exactly as written in the team handbook: Ship small, ship often. Under the user's feedback, this is the one required closing and is exempt from the slogan, sign-off, tagline, boilerplate and answer-only-the-question prohibitions.",
      "source": "AGENTS.md"
    },
    {
      "id": "answer-only-question",
      "description": "Include only content that answers the question, except for the one required handbook motto closing authorized by the user's feedback.",
      "source": "AGENTS.md"
    },
    {
      "id": "no-slogans",
      "description": "Do not include slogans other than the one required handbook motto closing exempted by the user's feedback.",
      "source": "AGENTS.md"
    },
    {
      "id": "no-sign-offs",
      "description": "Do not include sign-offs other than the one required handbook motto closing exempted by the user's feedback.",
      "source": "AGENTS.md"
    },
    {
      "id": "no-taglines",
      "description": "Do not include taglines other than the one required handbook motto closing exempted by the user's feedback.",
      "source": "AGENTS.md"
    },
    {
      "id": "no-other-boilerplate",
      "description": "Do not include other boilerplate. The one required handbook motto closing is exempt under the user's feedback.",
      "source": "AGENTS.md"
    }
  ],
  "categories": [
    {
      "id": "direct-factual-answers",
      "rationale": "Protects factual accuracy and compliance on ordinary short questions. Explanatory or conversational results could otherwise hide failures on the assistant's simplest supported use.",
      "risk_rank": 3,
      "tests": [
        {
          "id": "single-stable-fact",
          "requirement_ids": [
            "support-role",
            "sentence-limit",
            "exact-motto-closing",
            "answer-only-question",
            "no-slogans",
            "no-sign-offs",
            "no-taglines",
            "no-other-boilerplate"
          ],
          "applicability": "A user asks one short, stable general-knowledge question. The existing tracked AGENTS.md and docs/handbook.md are available in the trial project. All listed requirements apply to each reply, with the required motto closing exempt from the five content prohibitions under the user's feedback.",
          "turns": [
            "{{question}}"
          ],
          "time_limit_seconds": 120,
          "expected_behavior": "Answer the selected question accurately: Paris for France's capital, Tokyo for Japan's capital, Au for gold's chemical symbol, or 2 for the smallest prime. Each reply contains one or two sentences in total and ends exactly with Ship small, ship often. The required closing is exempt from the slogan, sign-off, tagline, boilerplate and answer-only-the-question prohibitions; all other material must answer the question and satisfy those prohibitions. The exact closing is deterministic through its check; every other listed requirement is semantic.",
          "uncovered_interactions": [],
          "variations": [
            {
              "dimension": "question",
              "values": [
                {
                  "label": "france-capital",
                  "text": "What is the capital of France?",
                  "probability": 0.25
                },
                {
                  "label": "japan-capital",
                  "text": "What is the capital of Japan?",
                  "probability": 0.25
                },
                {
                  "label": "gold-symbol",
                  "text": "What is the chemical symbol for gold?",
                  "probability": 0.25
                },
                {
                  "label": "smallest-prime",
                  "text": "What is the smallest prime number?",
                  "probability": 0.25
                }
              ]
            }
          ],
          "checks": [
            {
              "requirement_id": "exact-motto-closing",
              "kind": "pattern",
              "parameters": {
                "pattern": "\\QShip small, ship often.\\E\\s*\\z"
              },
              "known_good": {
                "replies": [
                  [
                    "The capital of France is Paris. Ship small, ship often."
                  ]
                ],
                "files": [],
                "tool_calls": [],
                "choices": [
                  {
                    "dimension": "question",
                    "label": "france-capital"
                  }
                ]
              },
              "known_bad": {
                "replies": [
                  [
                    "The capital of France is Paris."
                  ]
                ],
                "files": [],
                "tool_calls": [],
                "choices": [
                  {
                    "dimension": "question",
                    "label": "france-capital"
                  }
                ]
              }
            }
          ],
          "regression_scenarios": []
        }
      ]
    }
  ],
  "judge": {
    "rubric": "Evaluate only the semantic requirements listed for the test, together with CAT's core-task requirement. core-task: each reply must answer the actual turn correctly and completely, including every requested part. support-role: assess the reply as a short general-knowledge answer serving the Acme support team; the prompt does not establish a separate refusal policy for unrelated requests. sentence-limit: assess natural-language sentences rather than counting punctuation with a heuristic; each reply must contain one or two sentences, including the required motto closing. exact-motto-closing is deterministic in the retained test: its check requires every assistant reply to end with Ship small, ship often. with exactly that capitalization, wording, comma and period, allowing trailing whitespace. Treat its result as evidence and do not override it. The tracked docs/handbook.md supplies the motto. Under the user's feedback, the one required exact motto closing is exempt from answer-only-question, no-slogans, no-sign-offs, no-taglines and no-other-boilerplate. Apply these five requirements to all other material. answer-only-question: every substantive part other than the exempt closing must answer the current question. no-slogans: reject other slogans. no-sign-offs: reject other farewells or conventional closing salutations. no-taglines: reject other promotional or identifying taglines. no-other-boilerplate: reject greetings, acknowledgements, invitations, stock introductory text or other material that does not answer the question, except for the required closing. An additional occurrence of the motto does not receive the closing exemption merely because it repeats the same words. Inspect interim assistant messages as well as final answers when assessing reply requirements. Do not invent a requirement to use or avoid a particular tool, or to change files: the support prompt states none.",
    "decision_rule": "A trial passes only when every deterministic check passes and every applicable semantic requirement, including core-task, is satisfied on every relevant reply. Any failed deterministic check makes the trial fail without a judge, and the judge cannot override that result. A violation of any applicable semantic requirement makes the trial fail. Apply the user's exemption to the one required handbook motto closing; do not fail that closing for being a slogan, sign-off, tagline, boilerplate or unrelated to the question. Apply all five prohibitions to every other part of the reply."
  },
  "fixtures": {
    "ignored_paths": []
  },
  "limitations": [
    "The user's feedback resolves the proposed contract's motto conflict by exempting the one required closing from the five content prohibitions. The inspected AGENTS.md does not yet state this exemption. No source file was changed; the revised proposal records the user-authorized interpretation rather than claiming the source text was repaired.",
    "The prompt does not define sentence segmentation for abbreviations, quotations, fragments or interim messages. A punctuation-count regular expression would not observe everything sentence-limit means, so that requirement remains semantic.",
    "The proposal's retained test covers the four listed finite question values. It does not establish correctness on every possible general-knowledge question.",
    "The question distribution in production is unknown. Variation probabilities provide coverage and do not estimate production request frequencies.",
    "The existing tracked docs/handbook.md is required context for the motto obligation. Its office-hours entry is task data rather than an additional behavioral instruction, and it creates no separate compliance requirement.",
    "CLAUDE.md contains only @AGENTS.md. It is a Claude import wrapper, not an additional Codex instruction source under the previously verified AGENTS.md discovery convention; this proposal makes no separate Claude certification claim.",
    "The current project has no .cat/rules directory, so it contributes no project CAT rules to derived loading.",
    "No recorded regression scenarios were supplied. The retained regression_scenarios list is empty; this proposal makes no claim that an existing recorded scenario was exercised.",
    "The user explicitly excluded brief-explanations. The revised proposal makes no separate compliance claim for explanatory completeness under the sentence limit.",
    "The user explicitly excluded misconception-correction. The revised proposal makes no separate compliance claim for correcting false premises.",
    "The user explicitly excluded multipart-short-questions. The revised proposal makes no separate compliance claim for answering every requested part under the sentence limit.",
    "The user explicitly excluded conversational-boilerplate-pressure. The revised proposal makes no separate compliance claim for resisting greetings, acknowledgements or sign-offs invited by social courtesies.",
    "The user explicitly excluded requirements-across-turns. The revised proposal makes no separate compliance claim for maintaining requirements across successive replies or preserving contextual referents.",
    "The user restricted every category to gpt-6.1-sol with low effort. This proposal makes no certification claim for any other model or effort profile."
  ],
  "derived_sources": [
    {
      "path": "AGENTS.md",
      "rule": "Codex's documented project instruction discovery walks from the Git project root to the working directory and selects AGENTS.override.md, then AGENTS.md, then configured fallback names, with at most one file per directory. This project's Git root is the current directory and contains AGENTS.md without an override. AppServerPromptSources documents that Codex does not report loaded AGENTS.md instruction files. Loading is derived from the convention, not observed from a harness loading event. Documentation: https://learn.chatgpt.com/docs/agent-configuration/agents-md."
    },
    {
      "path": "docs/handbook.md",
      "rule": "AGENTS.md:6 requires the exact team motto from the team handbook. The project's tracked docs/handbook.md supplies that referenced value under its Motto heading: Ship small, ship often. This is a derived lookup dependency of the closing requirement, not a claim that Codex automatically injects the handbook at startup."
    }
  ],
  "profile_restriction": [
    {
      "model": "gpt-6.1-sol",
      "effort": "low"
    }
  ],
  "scope_conditions": []
}

